// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 value, bytes memory data) public {
        vm.assume(caller != c.owner());
        vm.assume(caller != address(0));
        vm.assume(value <= type(uint256).max / 2);
        vm.deal(caller, value);
        vm.prank(caller);
        bool ok;
        try c.sendMoney(address(0), value, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "Non-owner call to sendMoney should revert");
    }
}
